import React, { useState, useCallback, useEffect } from 'react';
import './Portfolio.css';

const events = [
  {
    title: 'Wedding Ceremony',
    photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
    description: 'Elegant wedding photography capturing every special moment.'
  },
  {
    title: 'Corporate Gala',
    photos: ['/GI_logo.png', '/GI_logo.png'],
    description: 'Professional event coverage for business galas and conferences.'
  },
  {
    title: 'Birthday Parties',
    photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
    description: 'Fun and vibrant birthday party memories, preserved forever.'
  },
  {
    title: 'Cultural Festivals',
    photos: ['/GI_logo.png', '/GI_logo.png'],
    description: 'Colorful and lively festival moments, full of tradition and joy.'
  },
  {
    title: 'Product Launches',
    photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
    description: 'Dynamic coverage of product launches and promotional events.'
  },
  {
    title: 'Family Gatherings',
    photos: ['/GI_logo.png', '/GI_logo.png'],
    description: 'Heartwarming family events, reunions, and celebrations.'
  }
];

const Portfolio = () => {
  const [lightbox, setLightbox] = useState({ open: false, src: '', alt: '' });

  const openLightbox = useCallback((src, alt) => {
    setLightbox({ open: true, src, alt });
  }, []);

  const closeLightbox = useCallback(() => {
    setLightbox({ open: false, src: '', alt: '' });
  }, []);

  useEffect(() => {
    if (!lightbox.open) return;
    const handleKey = (e) => {
      if (e.key === 'Escape') closeLightbox();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [lightbox.open, closeLightbox]);

  return (
    <div className="portfolio-bg">
      <div className="portfolio-header">
        <h1>Event Gallery</h1>
        <p>See highlights from the many events we’ve covered, grouped by event type.</p>
      </div>
      <div className="portfolio-event-list">
        {events.map((event, idx) => (
          <div className="portfolio-event-card" key={idx}>
            <div className="portfolio-event-accent" />
            <div className="portfolio-event-content">
              <div className="portfolio-event-header">
                <h2 className="portfolio-event-title">{event.title}</h2>
                <p className="portfolio-event-desc">{event.description}</p>
              </div>
              <div className="portfolio-photo-grid-pro">
                {event.photos.map((photo, pidx) => (
                  <div className="portfolio-photo-wrapper" key={pidx}>
                    <img
                      src={photo}
                      alt={event.title + ' photo ' + (pidx+1)}
                      className="portfolio-photo-pro"
                      onClick={() => openLightbox(photo, event.title + ' photo ' + (pidx+1))}
                      style={{ cursor: 'zoom-in' }}
                    />
                  </div>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>
      {lightbox.open && (
        <div className="portfolio-lightbox" onClick={closeLightbox}>
          <img
            src={lightbox.src}
            alt={lightbox.alt}
            className="portfolio-lightbox-img"
            onClick={e => e.stopPropagation()}
          />
          <button className="portfolio-lightbox-close" onClick={closeLightbox} aria-label="Close">&times;</button>
        </div>
      )}
    </div>
  );
};

export default Portfolio;
